def close_relay_capture(self) -> None:
    """Release only this thread's MSS handle after its monitor has stopped."""
    local = getattr(self, "_relay_capture_local", None)
    capture = getattr(local, "capture", None) if local is not None else None
    if capture is not None:
        del local.capture
        try:
            capture.close()
        except Exception:
            pass

