def detect_cookie_relay(png: bytes) -> CookieRelayProof | None:
    """Return a PNG-bound match or None, retaining the existing public API.

    Known calibration includes a 1600x900 game in a 1642x941 capture with
    41 px top chrome and a 42 px right toolbar. UI language must match
    the supplied English Relay prompt. Missing or ambiguous evidence fails closed.
    """
    if not isinstance(png, bytes) or not png or len(png) > _MAX_IMAGE_BYTES:
        return None
    try:
        with Image.open(io.BytesIO(png)) as source:
            width, height = source.size
            if (width < 640 or height < 360 or width * height > _MAX_IMAGE_PIXELS
                    or not 1.65 <= width / height <= 1.9):
                return None
            source.load()
            return _detect_cookie_relay_image(source, hashlib.sha256(png).hexdigest())
    except (OSError, ValueError, TypeError, KeyError, IndexError, Image.DecompressionBombError):
        return None


def detect_cookie_relay_frame(frame: Any) -> CookieRelayProof | None:
    """Use the exact same matcher on an immutable native RGB capture."""
    from visionstudio_cookie_relay_frame import RawRelayFrame
    if not isinstance(frame, RawRelayFrame):
        return None
    return _detect_cookie_relay_image(frame.image(), frame.frame_sha256)

