"""Immutable native pixels for the private Relay path; no input authority.

MSS supplies BGRx bytes. Convert them once to immutable RGB pixels instead of
encoding a PNG that every guard must decode again. Window identity, geometry,
freshness, Human Guard and durable input remain owned by the Bridge.
"""
from __future__ import annotations

from dataclasses import dataclass, field
import hashlib
import io
import math
import struct
from typing import Any, ClassVar

from PIL import Image, ImageChops


FRAME_FORMAT = "raw-rgb-v1"
RAW_RELAY_FRAME_VERSION = "1"
_MAX_PIXELS = 16_000_000
_MAX_PNG_BYTES = 16_000_000


def _size(value: Any) -> tuple[int, int]:
    if (not isinstance(value, tuple) or len(value) != 2
            or any(type(item) is not int or item <= 0 for item in value)
            or value[0] * value[1] > _MAX_PIXELS):
        raise ValueError("Relay raw frame has invalid dimensions")
    return value


@dataclass(frozen=True, slots=True)
class RawRelayFrame:
    """Pixels owned by one capture, with immutable metadata and pixel digest.

    The digest is explicitly a domain-separated RGB digest, not a PNG digest.
    ``image()`` returns an independent copy so a classifier cannot mutate the
    bytes used by another guard while retaining the original frame identity.
    """

    size: tuple[int, int]
    rgb: bytes = field(repr=False)
    captured_at: float
    hwnd: int
    bounds: tuple[int, int, int, int]
    frame_sha256: str = field(init=False)
    frame_format: ClassVar[str] = FRAME_FORMAT

    def __post_init__(self) -> None:
        width, height = _size(self.size)
        if type(self.rgb) is not bytes or len(self.rgb) != width * height * 3:
            raise ValueError("Relay raw frame has invalid RGB pixels")
        if (isinstance(self.captured_at, bool)
                or not isinstance(self.captured_at, (int, float))
                or not math.isfinite(self.captured_at) or self.captured_at < 0):
            raise ValueError("Relay raw frame has invalid capture time")
        if type(self.hwnd) is not int or self.hwnd <= 0:
            raise ValueError("Relay raw frame has invalid window identity")
        if (not isinstance(self.bounds, tuple) or len(self.bounds) != 4
                or any(type(item) is not int for item in self.bounds)
                or self.bounds[2:] != self.size):
            raise ValueError("Relay raw frame bounds do not match its pixels")
        digest = hashlib.sha256()
        digest.update(b"axiom-cookie-relay/raw-rgb-v1\0")
        digest.update(struct.pack(">II", width, height))
        digest.update(self.rgb)
        object.__setattr__(self, "frame_sha256", digest.hexdigest())

    @property
    def width(self) -> int:
        return self.size[0]

    @property
    def height(self) -> int:
        return self.size[1]

    @property
    def capture_size(self) -> tuple[int, int]:
        return self.size

    @property
    def encoding(self) -> str:
        return FRAME_FORMAT

    @classmethod
    def from_rgb(cls, size: tuple[int, int], rgb: Any, *, captured_at: float,
                 hwnd: int, bounds: tuple[int, int, int, int]) -> RawRelayFrame:
        _size(size)
        if not isinstance(rgb, (bytes, bytearray, memoryview)):
            raise ValueError("Relay capture did not supply RGB bytes")
        return cls(size, bytes(rgb), captured_at, hwnd, bounds)

    @classmethod
    def from_bgra(cls, size: tuple[int, int], bgra: Any, *, captured_at: float,
                  hwnd: int, bounds: tuple[int, int, int, int]) -> RawRelayFrame:
        width, height = _size(size)
        if not isinstance(bgra, (bytes, bytearray, memoryview)):
            raise ValueError("Relay capture did not supply BGRx bytes")
        # MSS 9/10 returns bytes; accepting a buffer also supports an immutable
        # snapshot of newer MSS buffers. The unused alpha byte is not opacity.
        owned = bytes(bgra)
        if len(owned) != width * height * 4:
            raise ValueError("Relay capture has an invalid BGRx buffer length")
        rgb = Image.frombytes("RGB", size, owned, "raw", "BGRX").tobytes()
        return cls(size, rgb, captured_at, hwnd, bounds)

    @classmethod
    def from_image(cls, image: Image.Image, *, captured_at: float, hwnd: int,
                   bounds: tuple[int, int, int, int]) -> RawRelayFrame:
        _size(image.size)
        return cls(image.size, image.convert("RGB").tobytes(), captured_at, hwnd, bounds)

    @classmethod
    def from_png(cls, png: bytes, *, captured_at: float, hwnd: int,
                 bounds: tuple[int, int, int, int]) -> RawRelayFrame:
        """Compatibility adapter; native Relay captures do not use this path."""
        if type(png) is not bytes or not png or len(png) > _MAX_PNG_BYTES:
            raise ValueError("Relay compatibility frame has invalid PNG bytes")
        with Image.open(io.BytesIO(png)) as image:
            _size(image.size)
            image.load()
            return cls.from_image(image, captured_at=captured_at, hwnd=hwnd, bounds=bounds)

    def image(self) -> Image.Image:
        return Image.frombytes("RGB", self.size, self.rgb)

    def to_png(self) -> bytes:
        """Serialize evidence after input or for a Human pause, never to decide input."""
        output = io.BytesIO()
        self.image().save(output, format="PNG", compress_level=1)
        return output.getvalue()


def frame_is_near_black(frame: RawRelayFrame, *, level: int, ratio: float) -> bool:
    """Same black-frame metric as the PNG capture guard, without decoding."""
    grayscale = frame.image().convert("L")
    grayscale.thumbnail((128, 128))
    histogram = grayscale.histogram()
    total = sum(histogram)
    return bool(total > 0 and sum(histogram[:level + 1]) / total >= ratio)


def compare_raw_relay_freshness(
    reference: RawRelayFrame,
    current: RawRelayFrame,
    region: tuple[int, int, int, int],
    *,
    thumbnail_size: tuple[int, int],
    pixel_delta: int,
) -> dict[str, Any]:
    """Exact Relay ROI metrics on owned pixels; this grants no input rights."""
    unavailable = {"reason": "frame_comparison_unavailable", "dimensions_match": None,
                   "region_mean_delta": None, "region_changed_ratio": None}
    if not isinstance(reference, RawRelayFrame) or not isinstance(current, RawRelayFrame):
        return unavailable
    if reference.size != current.size:
        return {**unavailable, "reason": "image_dimensions_changed", "dimensions_match": False,
                "reference_size": list(reference.size), "current_size": list(current.size)}
    if (not isinstance(region, tuple) or len(region) != 4
            or any(type(value) is not int for value in region)
            or region[0] < 0 or region[1] < 0 or region[2] <= 0 or region[3] <= 0
            or region[0] + region[2] > reference.width
            or region[1] + region[3] > reference.height):
        return {**unavailable, "reason": "target_region_invalid"}
    if reference.frame_sha256 == current.frame_sha256:
        return {"reason": "identical_pixels", "dimensions_match": True,
                "region_mean_delta": 0.0, "region_changed_ratio": 0.0}
    try:
        x, y, width, height = region
        box = (x, y, x + width, y + height)
        first = reference.image().crop(box).resize(thumbnail_size)
        second = current.image().crop(box).resize(thumbnail_size)
        histogram = ImageChops.difference(first, second).convert("L").histogram()
        total = sum(histogram)
        mean = sum(level * count for level, count in enumerate(histogram)) / (255.0 * total) if total else 0.0
        changed = sum(histogram[pixel_delta + 1:]) / total if total else 0.0
        return {"reason": "target_region_measured", "dimensions_match": True,
                "region_mean_delta": round(mean, 6), "region_changed_ratio": round(changed, 6)}
    except (OSError, TypeError, ValueError):
        return unavailable
